import{r as e}from"./rolldown-runtime-XKyaHtl9.js";import{R as t,V as n,d as r}from"./statusPalette-n81jC8nU.js";import{M as i,N as a,S as o,Xt as s,sn as c,x as l}from"./ImageViewer-CIa98AJm.js";import{An as u,Yn as d,fr as f,gr as p}from"./App-BwDvvWPj.js";import{bt as m,dt as h}from"./quickNotes-7cc7rw20.js";import{c as g,t as _}from"./jsx-runtime-COJRAs98.js";import{t as v}from"./useTranslation-DTMHzrI7.js";import{r as y}from"./planStore-w_A2XckK.js";import{t as b}from"./settingsStore-CW5Jw_K_.js";var x={name:`compass`,size:24,node:[[`circle`,{cx:`12`,cy:`12`,r:`10`,key:`1mglay`}],[`path`,{d:`m16.24 7.76-1.804 5.411a2 2 0 0 1-1.265 1.265L7.76 16.24l1.804-5.411a2 2 0 0 1 1.265-1.265z`,key:`9ktpf1`}]]};x.node;var S=n(x),C=e(g(),1),w=[{id:`priority`,t:{en:{q:`How do I set a task's priority?`,a:`Tap the task card to open it and pick a priority (P1 is the highest) in the side panel. While typing a new task you can also write p1, p2 or p3, for example "Send invoice p1".`,k:`priority urgent important high low p1 p2 p3 flag`},tr:{q:`Görevime nereden öncelik veririm?`,a:`Görev kartına dokunup açın, sağdaki panelden önceliği seçin (P1 en yüksek). Yeni görev yazarken sonuna p1, p2 ya da p3 de yazabilirsiniz, ör. "Faturayı gönder p1".`,k:`öncelik acil önemli yüksek düşük p1 p2 p3 bayrak sıralama`},es:{q:`¿Cómo pongo la prioridad de una tarea?`,a:`Toca la tarjeta para abrirla y elige la prioridad (P1 es la más alta) en el panel lateral. Al escribir una tarea nueva también puedes añadir p1, p2 o p3, p. ej. "Enviar factura p1".`,k:`prioridad urgente importante alta baja p1 p2 p3`},de:{q:`Wie lege ich die Priorität einer Aufgabe fest?`,a:`Tippe auf die Karte, um sie zu öffnen, und wähle im Seitenbereich die Priorität (P1 ist am höchsten). Beim Eintippen einer neuen Aufgabe kannst du auch p1, p2 oder p3 anhängen, z. B. "Rechnung senden p1".`,k:`priorität dringend wichtig hoch niedrig p1 p2 p3`},pt:{q:`Como defino a prioridade de uma tarefa?`,a:`Toque no cartão para abrir a tarefa e escolha a prioridade (P1 é a mais alta) no painel lateral. Ao digitar uma tarefa nova você também pode escrever p1, p2 ou p3, ex.: "Enviar fatura p1".`,k:`prioridade urgente importante alta baixa p1 p2 p3`},fr:{q:`Comment définir la priorité d'une tâche ?`,a:`Touchez la carte pour ouvrir la tâche et choisissez la priorité (P1 est la plus haute) dans le panneau latéral. En tapant une nouvelle tâche, vous pouvez aussi ajouter p1, p2 ou p3, par ex. « Envoyer la facture p1 ».`,k:`priorité urgent important haute basse p1 p2 p3`}}},{id:`share`,action:`share`,t:{en:{q:`How do I share a project with my client?`,a:`Open the project and tap Share in the project header. In three short steps you enter the client's name, choose how the page works (progress only, approved delivery or approval and payment) and which steps need approval, then tap Create link. Copy the link or send the ready message by WhatsApp or email. Your client doesn't need an account.`,k:`share client link send customer portal page invite external`},tr:{q:`Müşteri paylaşımını nereden yaparım?`,a:`Projeyi açın, proje başlığında Paylaş'a dokunun. Üç kısa adımda müşterinin adını yazar, sayfanın nasıl çalışacağını (yalnızca takip, onaylı teslim ya da onay ve ödeme) ve onay istenecek adımları seçer, Bağlantıyı oluştur'a basarsınız. Bağlantıyı kopyalayın ya da hazır mesajı WhatsApp veya e-postayla gönderin. Müşterinin hesap açması gerekmez.`,k:`paylaş paylaşım müşteri bağlantı link gönder portal sayfa dışarı davet`},es:{q:`¿Cómo comparto un proyecto con mi cliente?`,a:`Abre el proyecto y toca Compartir en la cabecera. En tres pasos escribes el nombre del cliente, eliges cómo funciona la página (solo seguimiento, entrega con aprobación o aprobación y pago) y qué pasos necesitan aprobación, y pulsas Crear el enlace. Copia el enlace o envía el mensaje listo por WhatsApp o correo. Tu cliente no necesita cuenta.`,k:`compartir cliente enlace enviar portal página invitar`},de:{q:`Wie teile ich ein Projekt mit meinem Kunden?`,a:`Öffne das Projekt und tippe in der Projektleiste auf Teilen. In drei kurzen Schritten gibst du den Kundennamen ein, wählst, wie die Seite funktioniert (nur verfolgen, Lieferung mit Freigabe oder Freigabe und Zahlung) und welche Schritte freigegeben werden, und tippst auf Link erstellen. Kopiere den Link oder schick die fertige Nachricht per WhatsApp oder E-Mail. Ein Konto ist nicht nötig.`,k:`teilen kunde link senden portal seite einladen extern`},pt:{q:`Como compartilho um projeto com meu cliente?`,a:`Abra o projeto e toque em Compartilhar no cabeçalho. Em três passos você digita o nome do cliente, escolhe como a página funciona (só acompanhamento, entrega com aprovação ou aprovação e pagamento) e quais etapas precisam de aprovação, e toca em Criar o link. Copie o link ou envie a mensagem pronta por WhatsApp ou e-mail. O cliente não precisa de conta.`,k:`compartilhar cliente link enviar portal página convidar`},fr:{q:`Comment partager un projet avec mon client ?`,a:`Ouvrez le projet et touchez Partager dans l'en-tête. En trois étapes, vous saisissez le nom du client, choisissez le fonctionnement de la page (suivi seulement, livraison avec validation ou validation et paiement) et les étapes à valider, puis touchez Créer le lien. Copiez le lien ou envoyez le message prêt par WhatsApp ou e-mail. Aucun compte n'est nécessaire.`,k:`partager client lien envoyer portail page inviter externe`}}},{id:`private-link`,action:`share`,t:{en:{q:`What is the private client link for?`,a:`It opens a page made only for your client: progress, steps, approvals, files and notes, without signing in. Internal notes, tags and assignments are never shown. The link can't be guessed; you can turn it off at any time and add a PIN for extra protection.`,k:`private link secret url what safe security pin password guest access`},tr:{q:`Özel bağlantı ne işe yarar?`,a:`Müşterinize özel bir sayfa açar: ilerleme, adımlar, onaylar, dosyalar ve notlar, giriş yapmadan. İç notlarınız, etiketler ve atamalar asla görünmez. Bağlantı tahmin edilemez; istediğiniz an kapatabilir, ek koruma için PIN koyabilirsiniz.`,k:`özel bağlantı gizli link adres ne işe yarar güvenli güvenlik pin şifre misafir erişim`},es:{q:`¿Para qué sirve el enlace privado?`,a:`Abre una página solo para tu cliente: avance, pasos, aprobaciones, archivos y notas, sin iniciar sesión. Las notas internas, etiquetas y asignaciones nunca se ven. El enlace no se puede adivinar; puedes desactivarlo cuando quieras y añadir un PIN.`,k:`enlace privado secreto url seguro seguridad pin contraseña invitado`},de:{q:`Wofür ist der private Kundenlink?`,a:`Er öffnet eine Seite nur für deinen Kunden: Fortschritt, Schritte, Freigaben, Dateien und Notizen, ohne Anmeldung. Interne Notizen, Tags und Zuweisungen sind nie sichtbar. Der Link ist nicht erratbar; du kannst ihn jederzeit abschalten und eine PIN setzen.`,k:`privater link geheim url sicher sicherheit pin passwort gast zugriff`},pt:{q:`Para que serve o link privado?`,a:`Ele abre uma página só para o seu cliente: progresso, etapas, aprovações, arquivos e notas, sem login. Notas internas, etiquetas e atribuições nunca aparecem. O link não pode ser adivinhado; você pode desativá-lo quando quiser e colocar um PIN.`,k:`link privado secreto url seguro segurança pin senha convidado acesso`},fr:{q:`À quoi sert le lien privé ?`,a:`Il ouvre une page réservée à votre client : avancement, étapes, validations, fichiers et notes, sans connexion. Les notes internes, étiquettes et attributions ne sont jamais visibles. Le lien est impossible à deviner ; vous pouvez le désactiver à tout moment et ajouter un code PIN.`,k:`lien privé secret url sûr sécurité pin mot de passe invité accès`}}},{id:`approvals`,action:`share`,t:{en:{q:`How does client approval work?`,a:`In Share, mark the steps the client should approve. When your work on a step is done, choose "Send for client approval" on the task: the deadline pauses and the client is notified. When they approve, the task completes; if they ask for changes, it comes back to you with their note.`,k:`approve approval client sign off review accept reject changes waiting`},tr:{q:`Müşteri onayı nasıl çalışır?`,a:`Paylaş'ta müşterinin onaylayacağı adımları işaretleyin. Bir adımdaki işiniz bitince görevde "Müşteri onayına gönder"i seçin: süre durur, müşteriye haber gider. Müşteri onaylarsa görev tamamlanır; düzeltme isterse notuyla size geri döner.`,k:`onay onayla müşteri onayı kabul reddet düzeltme bekliyor gözden geçir`},es:{q:`¿Cómo funciona la aprobación del cliente?`,a:`En Compartir, marca los pasos que el cliente debe aprobar. Cuando termines un paso, elige "Enviar a aprobación del cliente": el plazo se pausa y se avisa al cliente. Si aprueba, la tarea se completa; si pide cambios, vuelve a ti con su nota.`,k:`aprobar aprobación cliente revisar aceptar cambios`},de:{q:`Wie funktioniert die Kundenfreigabe?`,a:`Markiere unter Teilen die Schritte, die der Kunde freigeben soll. Wenn deine Arbeit fertig ist, wähle an der Aufgabe "Zur Kundenfreigabe senden": Die Frist pausiert und der Kunde wird benachrichtigt. Gibt er frei, ist die Aufgabe erledigt; wünscht er Änderungen, kommt sie mit seiner Notiz zurück.`,k:`freigabe freigeben kunde prüfen akzeptieren änderungen`},pt:{q:`Como funciona a aprovação do cliente?`,a:`Em Compartilhar, marque as etapas que o cliente deve aprovar. Quando terminar uma etapa, escolha "Enviar para aprovação do cliente": o prazo pausa e o cliente é avisado. Se ele aprovar, a tarefa é concluída; se pedir ajustes, ela volta para você com a nota.`,k:`aprovar aprovação cliente revisar aceitar ajustes`},fr:{q:`Comment fonctionne la validation client ?`,a:`Dans Partager, cochez les étapes à faire valider. Quand votre travail est fini, choisissez « Envoyer en validation client » : le délai est suspendu et le client est prévenu. S'il valide, la tâche est terminée ; s'il demande des modifications, elle vous revient avec sa note.`,k:`valider validation client relire accepter modifications`}}},{id:`revisions`,action:`share`,t:{en:{q:`How do revision limits and extra fees work?`,a:`In Share, open the link and turn on revisions. Set how many free revisions each step has, the fee for an extra one and how many days each paid request adds. When the free ones run out, the client sees the cost and the extra days before sending. Uncollected fees are shown on the link and on the Clients board.`,k:`revision revisions limit free extra fee charge cost scope creep days extend money`},tr:{q:`Revizyon hakkı ve ek ücret nasıl çalışır?`,a:`Paylaş'ta bağlantıyı açın ve revizyonları açın. Adım başına ücretsiz revizyon sayısını, ek revizyon ücretini ve ücretli her isteğin teslime kaç gün ekleyeceğini girin. Hak bitince müşteri ücreti ve ek günü göndermeden önce görür. Tahsil edilmemiş ücretler bağlantıda ve Müşteriler panosunda görünür.`,k:`revizyon hakkı sınır ücretsiz ek ücret para maliyet kapsam uzatma gün`},es:{q:`¿Cómo funcionan el límite de revisiones y el cargo extra?`,a:`En Compartir, abre el enlace y activa las revisiones. Define cuántas revisiones gratis tiene cada paso, el cargo por una extra y cuántos días suma cada solicitud de pago. Al agotarse, el cliente ve el costo y los días antes de enviar. Lo pendiente de cobro aparece en el enlace y en Clientes.`,k:`revisión límite gratis extra cargo costo días alcance`},de:{q:`Wie funktionieren Überarbeitungslimit und Zusatzgebühr?`,a:`Öffne unter Teilen den Link und aktiviere Überarbeitungen. Lege kostenlose Überarbeitungen pro Schritt, die Gebühr für eine weitere und die zusätzlichen Tage pro bezahlter Anfrage fest. Sind die freien aufgebraucht, sieht der Kunde Kosten und Tage vor dem Senden. Offene Gebühren stehen am Link und in der Kundenübersicht.`,k:`überarbeitung limit kostenlos gebühr kosten tage umfang`},pt:{q:`Como funcionam o limite de revisões e a taxa extra?`,a:`Em Compartilhar, abra o link e ative as revisões. Defina quantas revisões grátis cada etapa tem, a taxa por uma extra e quantos dias cada pedido pago acrescenta. Quando acabam, o cliente vê o custo e os dias antes de enviar. Valores não cobrados aparecem no link e em Clientes.`,k:`revisão limite grátis extra taxa custo dias escopo`},fr:{q:`Comment fonctionnent la limite de révisions et les frais ?`,a:`Dans Partager, ouvrez le lien et activez les révisions. Indiquez le nombre de révisions gratuites par étape, le prix d'une révision en plus et les jours ajoutés par demande payante. Une fois épuisées, le client voit le coût et les jours avant d'envoyer. Les montants non encaissés apparaissent sur le lien et dans Clients.`,k:`révision limite gratuite frais coût jours périmètre`}}},{id:`payments`,action:`share`,t:{en:{q:`How do payment steps (milestone billing) work?`,a:`In Share, open the link and pick the payment steps with their amounts, and add your own payment link (Stripe, PayPal...). After the client approves such a step they see "Pay now" and "I've paid". You get a notice, check the payment and tap Payment received: the step completes and the next steps start. TaskRack never handles the money.`,k:`payment invoice milestone billing pay paid deposit installment money stripe paypal`},tr:{q:`Ödeme adımları (aşamalı ödeme) nasıl çalışır?`,a:`Paylaş'ta bağlantıyı açıp ödeme adımlarını ve tutarlarını seçin, kendi ödeme bağlantınızı (Stripe, PayPal...) ekleyin. Müşteri o adımı onaylayınca "Şimdi öde" ve "Ödedim" düğmelerini görür. Size bildirim gelir; ödemeyi kontrol edip Ödeme alındı'ya basarsınız, adım tamamlanır ve sonraki adımlar başlar. Para TaskRack'e gelmez.`,k:`ödeme fatura hakediş aşama taksit kapora para stripe paypal ödedim`},es:{q:`¿Cómo funcionan los pasos de pago?`,a:`En Compartir, abre el enlace, elige los pasos de pago y sus importes y añade tu enlace de pago. Tras aprobar el paso, el cliente ve "Pagar ahora" y "Ya pagué". Recibes un aviso, verificas y pulsas Pago recibido: el paso se completa y empiezan los siguientes. TaskRack no maneja el dinero.`,k:`pago factura hito cobro anticipo cuota dinero`},de:{q:`Wie funktionieren Zahlungsschritte?`,a:`Öffne unter Teilen den Link, wähle die Zahlungsschritte mit Beträgen und füge deinen Zahlungslink hinzu. Nach der Freigabe sieht der Kunde "Jetzt bezahlen" und "Bezahlt". Du wirst benachrichtigt, prüfst und tippst auf Zahlung erhalten: Der Schritt ist erledigt, die nächsten starten. TaskRack berührt das Geld nie.`,k:`zahlung rechnung meilenstein anzahlung rate geld`},pt:{q:`Como funcionam as etapas de pagamento?`,a:`Em Compartilhar, abra o link, escolha as etapas de pagamento com valores e adicione seu link de pagamento. Depois de aprovar a etapa, o cliente vê "Pagar agora" e "Já paguei". Você é avisado, confere e toca em Pagamento recebido: a etapa conclui e as próximas começam. O TaskRack não movimenta o dinheiro.`,k:`pagamento fatura marco parcela sinal dinheiro pix`},fr:{q:`Comment fonctionnent les étapes de paiement ?`,a:`Dans Partager, ouvrez le lien, choisissez les étapes de paiement et leurs montants et ajoutez votre lien de paiement. Après validation, le client voit « Payer maintenant » et « J'ai payé ». Vous êtes prévenu, vérifiez et touchez Paiement reçu : l'étape se termine et les suivantes démarrent. TaskRack ne touche jamais l'argent.`,k:`paiement facture jalon acompte échéance argent`}}},{id:`client-templates`,action:`clientFlows`,t:{en:{q:`Can I reuse the same client flow for every client?`,a:`Yes. Set up the project once, then in Share choose Save this flow as a template. For each new client open Clients > Client templates, pick the template and type the client's name: the project, tasks and client link are created in one step. Write {client} anywhere to insert their name.`,k:`template reuse same flow repeat new client onboarding copy duplicate`},tr:{q:`Aynı akışı her müşteri için tekrar kurmam gerekiyor mu?`,a:`Hayır. Projeyi bir kez kurun, Paylaş'ta Bu akışı şablon yap'ı seçin. Her yeni müşteri için Müşteriler > Müşteri şablonları'nı açın, şablonu seçip müşterinin adını yazın; proje, görevler ve müşteri bağlantısı tek adımda hazır olur. Metinlere {client} yazarsanız müşterinin adı konur.`,k:`şablon tekrar aynı akış yeni müşteri kopyala çoğalt hazır`},es:{q:`¿Puedo reutilizar el mismo flujo para cada cliente?`,a:`Sí. Configura el proyecto una vez y en Compartir elige Guardar este flujo como plantilla. Para cada cliente nuevo abre Clientes > Plantillas de cliente, elige la plantilla y escribe su nombre: proyecto, tareas y enlace quedan listos. Escribe {client} para insertar su nombre.`,k:`plantilla reutilizar mismo flujo nuevo cliente copiar`},de:{q:`Kann ich denselben Ablauf für jeden Kunden nutzen?`,a:`Ja. Richte das Projekt einmal ein und wähle unter Teilen Diesen Ablauf als Vorlage speichern. Für jeden neuen Kunden öffnest du Kunden > Kundenvorlagen, wählst die Vorlage und gibst den Namen ein: Projekt, Aufgaben und Link sind fertig. {client} setzt den Namen ein.`,k:`vorlage wiederverwenden ablauf neuer kunde kopieren`},pt:{q:`Posso reutilizar o mesmo fluxo para cada cliente?`,a:`Sim. Monte o projeto uma vez e em Compartilhar escolha Salvar este fluxo como modelo. Para cada cliente novo abra Clientes > Modelos de cliente, escolha o modelo e digite o nome: projeto, tarefas e link ficam prontos. Escreva {client} para inserir o nome.`,k:`modelo reutilizar mesmo fluxo novo cliente copiar`},fr:{q:`Puis-je réutiliser le même parcours pour chaque client ?`,a:`Oui. Préparez le projet une fois puis, dans Partager, choisissez Enregistrer ce parcours comme modèle. Pour chaque nouveau client, ouvrez Clients > Modèles client, choisissez le modèle et tapez son nom : projet, tâches et lien sont prêts. {client} insère son nom.`,k:`modèle réutiliser même parcours nouveau client copier`}}},{id:`client-view`,t:{en:{q:`How can I see exactly what my client sees?`,a:`Tap the eye icon at the end of the project header (Client view). The client page opens as a preview: nothing you do there is saved or counted as a visit. You can also use Preview as your client in Share.`,k:`preview client view see what client sees eye hidden internal private check`},tr:{q:`Müşterimin ne gördüğünü nasıl görürüm?`,a:`Proje başlığının sonundaki göz simgesine (Müşteri gözüyle) dokunun. Müşteri sayfası önizleme olarak açılır; orada yaptıklarınız kaydedilmez ve ziyaret sayılmaz. Paylaş'taki Müşteri gözüyle önizle de aynı işi yapar.`,k:`önizleme müşteri gözüyle ne görüyor göz gizli iç not kontrol`},es:{q:`¿Cómo veo exactamente lo que ve mi cliente?`,a:`Toca el icono del ojo al final de la cabecera del proyecto (Vista del cliente). La página del cliente se abre como vista previa: nada se guarda ni cuenta como visita. También está Ver como tu cliente en Compartir.`,k:`vista previa cliente ver ojo interno privado`},de:{q:`Wie sehe ich, was mein Kunde sieht?`,a:`Tippe auf das Augensymbol am Ende der Projektleiste (Kundenansicht). Die Kundenseite öffnet sich als Vorschau: Nichts wird gespeichert oder als Besuch gezählt. Auch Als Kunde ansehen unter Teilen geht.`,k:`vorschau kundenansicht sehen auge intern privat`},pt:{q:`Como vejo exatamente o que o cliente vê?`,a:`Toque no ícone de olho no fim do cabeçalho do projeto (Visão do cliente). A página do cliente abre como prévia: nada é salvo nem contado como visita. Também há Ver como o cliente em Compartilhar.`,k:`prévia visão do cliente ver olho interno privado`},fr:{q:`Comment voir exactement ce que voit mon client ?`,a:`Touchez l'icône en forme d'œil à la fin de l'en-tête du projet (Vue client). La page client s'ouvre en aperçu : rien n'est enregistré ni compté comme visite. Voir comme votre client dans Partager fonctionne aussi.`,k:`aperçu vue client voir œil interne privé`}}},{id:`clients-board`,action:`clients`,t:{en:{q:`Where can I see all my clients at once?`,a:`Open Clients from the side menu. Every client link is listed with progress, pending approvals, payment notices, uncollected fees and clients who haven't opened their page for a while. Items that need attention are on top.`,k:`clients board overview all customers dashboard list ghost visits unpaid`},tr:{q:`Bütün müşterilerimi tek yerde nerede görürüm?`,a:`Sol menüden Müşteriler'i açın. Her müşteri bağlantısı ilerleme, bekleyen onay, ödeme bildirimi, tahsil edilmemiş ücret ve uzun süredir sayfayı açmayan müşteri bilgisiyle listelenir. Dikkat isteyenler üsttedir.`,k:`müşteriler pano liste tümü genel bakış ziyaret ödenmemiş açmadı`},es:{q:`¿Dónde veo todos mis clientes a la vez?`,a:`Abre Clientes en el menú lateral. Cada enlace aparece con avance, aprobaciones pendientes, avisos de pago, cargos sin cobrar y clientes que no abren su página. Lo urgente va arriba.`,k:`clientes panel resumen todos lista visitas`},de:{q:`Wo sehe ich alle Kunden auf einen Blick?`,a:`Öffne Kunden im Seitenmenü. Jeder Kundenlink steht dort mit Fortschritt, offenen Freigaben, Zahlungsmeldungen, offenen Gebühren und Kunden, die ihre Seite länger nicht geöffnet haben. Dringendes steht oben.`,k:`kunden übersicht alle liste besuche`},pt:{q:`Onde vejo todos os clientes de uma vez?`,a:`Abra Clientes no menu lateral. Cada link aparece com progresso, aprovações pendentes, avisos de pagamento, valores não cobrados e clientes que não abrem a página. O que precisa de atenção fica no topo.`,k:`clientes painel visão geral todos lista visitas`},fr:{q:`Où voir tous mes clients d'un coup ?`,a:`Ouvrez Clients dans le menu latéral. Chaque lien y figure avec l'avancement, les validations en attente, les avis de paiement, les frais non encaissés et les clients qui n'ouvrent plus leur page. L'urgent est en haut.`,k:`clients tableau vue d'ensemble tous liste visites`}}},{id:`client-message`,action:`clientCapture`,t:{en:{q:`Can I turn a client's email or WhatsApp messages into tasks?`,a:`Yes. Open AI and choose Turn a client message into tasks, then paste the email or chat. It is split into tasks, subtasks, due dates and priorities; you review the list before anything is added.`,k:`email whatsapp message paste convert tasks chat client text split meeting notes`},tr:{q:`Müşterinin e-postasını ya da WhatsApp mesajlarını göreve çevirebilir miyim?`,a:`Evet. Yapay zekâ'yı açıp Müşteri mesajını görevlere çevirin'i seçin, e-postayı ya da yazışmayı yapıştırın. Görevlere, alt görevlere, tarihlere ve önceliğe bölünür; eklemeden önce listeyi siz onaylarsınız.`,k:`e-posta mail whatsapp mesaj yapıştır göreve çevir yazışma müşteri böl`},es:{q:`¿Puedo convertir correos o mensajes de WhatsApp en tareas?`,a:`Sí. Abre IA, elige Convierte un mensaje del cliente en tareas y pega el correo o el chat. Se divide en tareas, subtareas, fechas y prioridades; revisas la lista antes de añadir.`,k:`correo whatsapp mensaje pegar convertir tareas chat`},de:{q:`Kann ich Kunden-E-Mails oder WhatsApp in Aufgaben umwandeln?`,a:`Ja. Öffne KI, wähle Kundennachricht in Aufgaben verwandeln und füge die E-Mail oder den Chat ein. Er wird in Aufgaben, Teilaufgaben, Termine und Prioritäten aufgeteilt; du prüfst die Liste vorher.`,k:`email whatsapp nachricht einfügen umwandeln aufgaben chat`},pt:{q:`Posso transformar e-mails ou mensagens de WhatsApp em tarefas?`,a:`Sim. Abra IA, escolha Transforme a mensagem do cliente em tarefas e cole o e-mail ou a conversa. Ela vira tarefas, subtarefas, prazos e prioridades; você revisa a lista antes.`,k:`email whatsapp mensagem colar transformar tarefas conversa`},fr:{q:`Puis-je transformer des e-mails ou messages WhatsApp en tâches ?`,a:`Oui. Ouvrez IA, choisissez Transformer un message client en tâches et collez l'e-mail ou la conversation. Il est découpé en tâches, sous-tâches, échéances et priorités ; vous validez la liste avant l'ajout.`,k:`email whatsapp message coller transformer tâches conversation`}}},{id:`pages`,t:{en:{q:`How do I create a new project or page?`,a:`Click the project name at the top left of the canvas and choose New project (or use New project in the side menu). Each project is a separate board; tasks, notes and client links belong to the project.`,k:`page project new create board tab workspace folder`},tr:{q:`Yeni proje nasıl açarım?`,a:`Tuvalin sol üstündeki proje adına dokunup Yeni proje'yi seçin (ya da yan menüdeki Yeni proje). Her proje ayrı bir panodur; görevler, notlar ve müşteri bağlantıları projeye aittir.`,k:`sayfa proje yeni oluştur pano sekme klasör`},es:{q:`¿Cómo creo un proyecto o página nueva?`,a:`Toca el nombre del proyecto arriba a la izquierda del lienzo y elige Nuevo proyecto (o usa Nuevo proyecto en el menú lateral). Cada proyecto es un tablero propio con sus tareas, notas y enlaces de cliente.`,k:`página proyecto nuevo crear tablero pestaña`},de:{q:`Wie lege ich ein neues Projekt oder eine Seite an?`,a:`Tippe oben links auf der Fläche auf den Projektnamen und wähle Neues Projekt (oder Neues Projekt im Seitenmenü). Jedes Projekt ist ein eigenes Board mit eigenen Aufgaben, Notizen und Kundenlinks.`,k:`seite projekt neu erstellen board tab`},pt:{q:`Como crio um projeto ou página nova?`,a:`Toque no nome do projeto no canto superior esquerdo da tela e escolha Novo projeto (ou use Novo projeto no menu lateral). Cada projeto é um quadro próprio com tarefas, notas e links de cliente.`,k:`página projeto novo criar quadro aba`},fr:{q:`Comment créer un nouveau projet ou une page ?`,a:`Touchez le nom du projet en haut à gauche du canevas et choisissez Nouveau projet (ou Nouveau projet dans le menu latéral). Chaque projet est un tableau à part avec ses tâches, notes et liens client.`,k:`page projet nouveau créer tableau onglet`}}},{id:`dependencies`,t:{en:{q:`How do I connect tasks so one waits for another?`,a:`Drag from the dot on the right of a task card to the next task. The next task is locked until the previous one is done. On a phone, open the task and use "Link to another task".`,k:`connect link dependency arrow line order sequence before after blocked wait chain`},tr:{q:`Görevleri birbirine nasıl bağlarım, biri diğerini beklesin?`,a:`Görev kartının sağındaki noktadan sürükleyip sonraki göreve bırakın. Sonraki görev, önceki bitene kadar kilitli kalır. Telefonda görevi açıp "Başka göreve bağla"yı kullanın.`,k:`bağla bağlantı bağımlılık ok çizgi sıra önce sonra kilitli bekle zincir`},es:{q:`¿Cómo conecto tareas para que una espere a otra?`,a:`Arrastra desde el punto derecho de la tarjeta hasta la tarea siguiente. Esta queda bloqueada hasta que termine la anterior. En el móvil, abre la tarea y usa "Vincular con otra tarea".`,k:`conectar dependencia flecha orden antes después bloqueada`},de:{q:`Wie verbinde ich Aufgaben, damit eine auf die andere wartet?`,a:`Zieh vom Punkt rechts an der Karte zur nächsten Aufgabe. Diese bleibt gesperrt, bis die vorherige erledigt ist. Am Handy öffnest du die Aufgabe und nutzt "Mit anderer Aufgabe verbinden".`,k:`verbinden abhängigkeit pfeil reihenfolge vorher nachher gesperrt`},pt:{q:`Como ligo tarefas para uma esperar a outra?`,a:`Arraste do ponto à direita do cartão até a próxima tarefa. Ela fica bloqueada até a anterior terminar. No celular, abra a tarefa e use "Ligar a outra tarefa".`,k:`ligar conectar dependência seta ordem antes depois bloqueada`},fr:{q:`Comment relier des tâches pour qu'une attende l'autre ?`,a:`Faites glisser le point à droite de la carte vers la tâche suivante. Celle-ci reste verrouillée jusqu'à la fin de la précédente. Sur téléphone, ouvrez la tâche et utilisez « Relier à une autre tâche ».`,k:`relier dépendance flèche ordre avant après verrouillée`}}},{id:`dates`,t:{en:{q:`How do I set a due date or reminder?`,a:`Open the task and set the due date in the side panel; you can add reminders there too. While typing you can write things like "tomorrow 3pm" or "friday".`,k:`due date deadline reminder time schedule when tomorrow alarm notify`},tr:{q:`Bitiş tarihi ya da hatırlatma nasıl koyarım?`,a:`Görevi açın, sağdaki panelden bitiş tarihini seçin; hatırlatmaları da oradan eklersiniz. Yazarken "yarın 15:00" ya da "cuma" gibi ifadeler de kullanabilirsiniz.`,k:`bitiş tarihi süre tarih hatırlatma saat ne zaman yarın alarm bildirim`},es:{q:`¿Cómo pongo fecha límite o recordatorio?`,a:`Abre la tarea y elige la fecha en el panel lateral; ahí añades recordatorios. Al escribir puedes usar "mañana 15:00" o "viernes".`,k:`fecha límite vencimiento recordatorio hora mañana alarma`},de:{q:`Wie setze ich ein Fälligkeitsdatum oder eine Erinnerung?`,a:`Öffne die Aufgabe und wähle das Datum im Seitenbereich; dort fügst du auch Erinnerungen hinzu. Beim Tippen gehen auch "morgen 15 Uhr" oder "Freitag".`,k:`fällig datum frist erinnerung uhrzeit morgen alarm`},pt:{q:`Como coloco prazo ou lembrete?`,a:`Abra a tarefa e escolha a data no painel lateral; lá você adiciona lembretes. Ao digitar pode usar "amanhã 15h" ou "sexta".`,k:`prazo data vencimento lembrete hora amanhã alarme`},fr:{q:`Comment mettre une échéance ou un rappel ?`,a:`Ouvrez la tâche et choisissez la date dans le panneau latéral ; vous y ajoutez aussi des rappels. En tapant, « demain 15h » ou « vendredi » fonctionnent.`,k:`échéance date délai rappel heure demain alarme`}}},{id:`agenda`,t:{en:{q:`What is "To review" at the top right?`,a:`Everything TaskRack needs to ask you waits there, one question at a time: overdue tasks, moving late work to free hours, client reminders and your first steps. Open it whenever you like; it opens by itself only for something important. Overdue tasks no longer show questions on the card.`,k:`to review questions overdue late reminder first steps popup notice badge`},tr:{q:`Sağ üstteki "Gündem" nedir?`,a:`TaskRack'in size soracağı her şey orada, bir seferde bir soru olarak bekler: süresi geçen görevler, yetişmeyen işleri boş saatlere taşıma, müşteri hatırlatmaları ve ilk adımlar. İstediğiniz zaman açarsınız; yalnızca önemli bir şey varsa kendiliğinden açılır. Süresi geçen görevin kartında artık soru çıkmaz.`,k:`gündem soru süresi geçti gecikti hatırlatma ilk adımlar uyarı bildirim rozet`},es:{q:`¿Qué es "Por revisar" arriba a la derecha?`,a:`Todo lo que TaskRack necesita preguntarte espera ahí, una pregunta a la vez: tareas vencidas, mover trabajo atrasado a horas libres, recordatorios de clientes y tus primeros pasos. Ábrelo cuando quieras; solo se abre solo si hay algo importante. Las tareas vencidas ya no muestran preguntas en la tarjeta.`,k:`por revisar preguntas vencida atrasada recordatorio primeros pasos aviso`},de:{q:`Was ist "Zu prüfen" oben rechts?`,a:`Alles, was TaskRack Sie fragen möchte, wartet dort, eine Frage nach der anderen: überfällige Aufgaben, verspätete Arbeit in freie Stunden verschieben, Kundenerinnerungen und Ihre ersten Schritte. Öffnen Sie es, wann Sie möchten; es öffnet sich nur bei etwas Wichtigem von selbst. Überfällige Aufgaben zeigen keine Fragen mehr auf der Karte.`,k:`zu prüfen fragen überfällig verspätet erinnerung erste schritte hinweis`},pt:{q:`O que é "Para revisar" no canto superior direito?`,a:`Tudo o que o TaskRack precisa perguntar espera ali, uma pergunta por vez: tarefas atrasadas, mover trabalho atrasado para horários livres, lembretes de clientes e seus primeiros passos. Abra quando quiser; só abre sozinho se houver algo importante. Tarefas atrasadas não mostram mais perguntas no cartão.`,k:`para revisar perguntas atrasada vencida lembrete primeiros passos aviso`},fr:{q:`Qu'est-ce que « À voir » en haut à droite ?`,a:`Tout ce que TaskRack doit vous demander attend là, une question à la fois : tâches en retard, déplacer le travail en retard vers des heures libres, rappels clients et vos premiers pas. Ouvrez-le quand vous voulez ; il ne s'ouvre seul que pour quelque chose d'important. Les tâches en retard n'affichent plus de questions sur la carte.`,k:`à voir questions retard échéance rappel premiers pas avis`}}},{id:`recurring`,t:{en:{q:`How do I make a task repeat?`,a:`Open the task and choose Repeat (daily, weekdays, weekly or monthly) in the side panel. When you complete it, the next one is created automatically.`,k:`repeat recurring every day week month routine habit again`},tr:{q:`Tekrarlayan görev nasıl yaparım?`,a:`Görevi açıp sağdaki panelden Tekrar'ı seçin (her gün, hafta içi, haftalık, aylık). Tamamladığınızda bir sonraki kendiliğinden oluşur.`,k:`tekrar tekrarlayan her gün haftalık aylık rutin alışkanlık yine`},es:{q:`¿Cómo hago que una tarea se repita?`,a:`Abre la tarea y elige Repetir (diaria, entre semana, semanal o mensual). Al completarla se crea la siguiente.`,k:`repetir recurrente diario semanal mensual rutina`},de:{q:`Wie wiederhole ich eine Aufgabe?`,a:`Öffne die Aufgabe und wähle Wiederholen (täglich, werktags, wöchentlich, monatlich). Beim Erledigen entsteht automatisch die nächste.`,k:`wiederholen wiederkehrend täglich wöchentlich monatlich routine`},pt:{q:`Como faço uma tarefa se repetir?`,a:`Abra a tarefa e escolha Repetir (diária, dias úteis, semanal ou mensal). Ao concluir, a próxima é criada.`,k:`repetir recorrente diária semanal mensal rotina`},fr:{q:`Comment rendre une tâche récurrente ?`,a:`Ouvrez la tâche et choisissez Répéter (quotidienne, jours ouvrés, hebdomadaire ou mensuelle). En la terminant, la suivante est créée.`,k:`répéter récurrente quotidienne hebdomadaire mensuelle routine`}}},{id:`team`,action:`teamCreate`,t:{en:{q:`How do I create a team and invite people?`,a:`Open the workspace switcher at the top left and choose Create team. Then share the invite link or code; people join with their own account. You decide who can see, complete and assign tasks.`,k:`team create invite member colleague join workspace add people staff`},tr:{q:`Ekip nasıl kurarım, kişileri nasıl davet ederim?`,a:`Sol üstteki çalışma alanı seçicisini açıp Ekip kur'u seçin. Ardından davet bağlantısını ya da kodu paylaşın; kişiler kendi hesaplarıyla katılır. Kimin görevleri görüp tamamlayacağına ve atayacağına siz karar verirsiniz.`,k:`ekip takım kur davet üye çalışma arkadaşı katıl çalışma alanı kişi ekle`},es:{q:`¿Cómo creo un equipo e invito personas?`,a:`Abre el selector de espacio arriba a la izquierda y elige Crear equipo. Comparte el enlace o código de invitación; cada persona entra con su cuenta. Tú decides quién ve, completa y asigna.`,k:`equipo crear invitar miembro unirse personas`},de:{q:`Wie gründe ich ein Team und lade Leute ein?`,a:`Öffne oben links die Bereichsauswahl und wähle Team erstellen. Teile dann Einladungslink oder Code; jeder tritt mit eigenem Konto bei. Du legst fest, wer sehen, erledigen und zuweisen darf.`,k:`team erstellen einladen mitglied beitreten personen`},pt:{q:`Como crio uma equipe e convido pessoas?`,a:`Abra o seletor de espaço no canto superior esquerdo e escolha Criar equipe. Compartilhe o link ou código de convite; cada um entra com sua conta. Você decide quem vê, conclui e atribui.`,k:`equipe time criar convidar membro entrar pessoas`},fr:{q:`Comment créer une équipe et inviter des personnes ?`,a:`Ouvrez le sélecteur d'espace en haut à gauche et choisissez Créer une équipe. Partagez le lien ou le code d'invitation ; chacun rejoint avec son compte. Vous décidez qui voit, termine et attribue.`,k:`équipe créer inviter membre rejoindre personnes`}}},{id:`assign`,t:{en:{q:`How do I assign a task to someone?`,a:`In a team, open the task and choose people in the Team section, or drag tasks between people on the Team board (Assignments tab). The person gets a notification with your note.`,k:`assign delegate give owner responsible person member team board workload`},tr:{q:`Görevi birine nasıl atarım?`,a:`Ekipte görevi açın ve Ekip bölümünden kişileri seçin ya da Ekip panosunun Atama sekmesinde görevleri kişiler arasında sürükleyin. Kişiye notunuzla birlikte bildirim gider.`,k:`ata atama devret ver sorumlu kişi üye ekip panosu iş yükü`},es:{q:`¿Cómo asigno una tarea a alguien?`,a:`En un equipo, abre la tarea y elige personas en la sección Equipo, o arrastra tareas entre personas en el panel del equipo. La persona recibe un aviso con tu nota.`,k:`asignar delegar responsable persona miembro equipo`},de:{q:`Wie weise ich eine Aufgabe jemandem zu?`,a:`Öffne im Team die Aufgabe und wähle Personen im Bereich Team, oder zieh Aufgaben in der Teamübersicht zwischen Personen. Die Person wird mit deiner Notiz benachrichtigt.`,k:`zuweisen delegieren verantwortlich person mitglied team`},pt:{q:`Como atribuo uma tarefa a alguém?`,a:`Na equipe, abra a tarefa e escolha pessoas na seção Equipe, ou arraste tarefas entre pessoas no painel da equipe. A pessoa recebe um aviso com sua nota.`,k:`atribuir delegar responsável pessoa membro equipe`},fr:{q:`Comment attribuer une tâche à quelqu'un ?`,a:`Dans une équipe, ouvrez la tâche et choisissez des personnes dans la section Équipe, ou faites glisser les tâches entre personnes dans le tableau d'équipe. La personne est prévenue avec votre note.`,k:`attribuer déléguer responsable personne membre équipe`}}},{id:`quick-notes`,action:`quickNotes`,t:{en:{q:`How do quick notes and the note shortcut work?`,a:`Notes > Quick notes keeps short ideas with optional reminders. On the computer, press the shortcut (Ctrl+Shift+Space by default) in any app to open the note strip; pin it to keep a small notes panel open while you type elsewhere. Each note can be copied or turned into a task.`,k:`quick note notes shortcut hotkey strip pin copy remind idea memo sticky`},tr:{q:`Hızlı notlar ve not kısayolu nasıl çalışır?`,a:`Notlar > Hızlı notlar kısa fikirleri tutar, isterseniz hatırlatma kurarsınız. Bilgisayarda hangi uygulamada olursanız olun kısayola (varsayılan Ctrl+Shift+Boşluk) basınca not şeridi açılır; sabitlerseniz başka yerde yazarken küçük bir not paneli açık kalır. Her not kopyalanabilir ya da göreve çevrilebilir.`,k:`hızlı not notlar kısayol tuş şerit sabitle kopyala hatırlat fikir yapışkan`},es:{q:`¿Cómo funcionan las notas rápidas y el atajo?`,a:`Notas > Notas rápidas guarda ideas cortas con recordatorio opcional. En el ordenador, pulsa el atajo (Ctrl+Shift+Espacio) en cualquier app para abrir la barra de notas; fíjala para mantener un panel abierto mientras escribes en otro lado. Cada nota se puede copiar o convertir en tarea.`,k:`nota rápida atajo fijar copiar recordatorio idea`},de:{q:`Wie funktionieren schnelle Notizen und das Tastenkürzel?`,a:`Notizen > Schnelle Notizen speichert kurze Ideen mit optionaler Erinnerung. Am Computer öffnet das Kürzel (Strg+Umschalt+Leertaste) in jeder App die Notizleiste; angeheftet bleibt ein kleines Notizfenster offen, während du woanders schreibst. Jede Notiz lässt sich kopieren oder in eine Aufgabe umwandeln.`,k:`schnelle notiz kürzel anheften kopieren erinnerung idee`},pt:{q:`Como funcionam as notas rápidas e o atalho?`,a:`Notas > Notas rápidas guarda ideias curtas com lembrete opcional. No computador, o atalho (Ctrl+Shift+Espaço) abre a faixa de notas em qualquer app; fixe para manter um painel aberto enquanto digita em outro lugar. Cada nota pode ser copiada ou virar tarefa.`,k:`nota rápida atalho fixar copiar lembrete ideia`},fr:{q:`Comment fonctionnent les notes rapides et le raccourci ?`,a:`Notes > Notes rapides garde de courtes idées avec rappel facultatif. Sur ordinateur, le raccourci (Ctrl+Maj+Espace) ouvre la barre de notes dans n'importe quelle app ; épinglez-la pour garder un petit panneau ouvert pendant que vous écrivez ailleurs. Chaque note peut être copiée ou transformée en tâche.`,k:`note rapide raccourci épingler copier rappel idée`}}},{id:`capture`,action:`capture`,t:{en:{q:`Can I add many tasks at once by talking?`,a:`Yes. Open AI > Tell me, I'll organize it and say or type everything on your mind. It becomes separate tasks in the right projects and updates existing ones; nothing changes until you confirm.`,k:`voice speak dictate many tasks at once ai organize capture brain dump`},tr:{q:`Konuşarak birden çok görevi tek seferde ekleyebilir miyim?`,a:`Evet. Yapay zekâ > Anlatın, yerleştireyim'i açın, aklınızdakileri söyleyin ya da yazın. Ayrı görevlere bölünür, doğru projeye yerleşir, var olan görevler güncellenir; siz onaylamadan hiçbir şey değişmez.`,k:`konuş ses söyle çok görev tek seferde yapay zekâ anlatın yerleştireyim`},es:{q:`¿Puedo añadir muchas tareas a la vez hablando?`,a:`Sí. Abre IA > Cuéntame y lo organizo y di o escribe todo lo que tengas en mente. Se convierte en tareas en los proyectos correctos; nada cambia hasta que confirmes.`,k:`voz hablar dictar muchas tareas ia organizar`},de:{q:`Kann ich viele Aufgaben auf einmal per Sprache anlegen?`,a:`Ja. Öffne KI > Erzähl es mir, ich sortiere es und sprich oder tippe alles. Es wird in Aufgaben in den richtigen Projekten aufgeteilt; nichts ändert sich ohne deine Bestätigung.`,k:`sprache sprechen diktieren viele aufgaben ki sortieren`},pt:{q:`Posso adicionar várias tarefas de uma vez falando?`,a:`Sim. Abra IA > Me conte que eu organizo e fale ou digite tudo. Vira tarefas nos projetos certos; nada muda até você confirmar.`,k:`voz falar ditar várias tarefas ia organizar`},fr:{q:`Puis-je ajouter plusieurs tâches d'un coup en parlant ?`,a:`Oui. Ouvrez IA > Racontez, je range et dites ou tapez tout. Cela devient des tâches dans les bons projets ; rien ne change sans votre accord.`,k:`voix parler dicter plusieurs tâches ia ranger`}}},{id:`ai-limits`,action:`upgrade`,t:{en:{q:`Why did AI stop working? How do AI limits work?`,a:`Each paid plan has a monthly AI allowance. When it runs out, AI features pause until next month unless you buy an extra credit pack (Settings > AI). The rest of the app keeps working. This help assistant does not use your allowance.`,k:`ai limit allowance credit quota stopped not working usage month pack`},tr:{q:`Yapay zekâ neden durdu? Kullanım hakkı nasıl işler?`,a:`Her ücretli pakette aylık yapay zekâ hakkı vardır. Bitince ek kredi paketi almazsanız (Ayarlar > Yapay zekâ) yapay zekâ özellikleri ay sonuna kadar durur; uygulamanın geri kalanı çalışır. Bu yardım asistanı hakkınızdan düşmez.`,k:`yapay zekâ hak sınır kredi kota durdu çalışmıyor kullanım ay paket`},es:{q:`¿Por qué se detuvo la IA? ¿Cómo funciona el límite?`,a:`Cada plan de pago tiene un cupo mensual de IA. Si se agota, las funciones de IA se pausan hasta el mes siguiente salvo que compres créditos extra (Ajustes > IA). El resto funciona. Este asistente de ayuda no consume tu cupo.`,k:`ia límite cupo créditos detenida uso mes`},de:{q:`Warum funktioniert die KI nicht mehr?`,a:`Jeder bezahlte Plan hat ein monatliches KI-Kontingent. Ist es aufgebraucht, pausieren KI-Funktionen bis zum nächsten Monat, außer du kaufst Zusatzguthaben (Einstellungen > KI). Der Rest läuft weiter. Diese Hilfe verbraucht kein Kontingent.`,k:`ki limit kontingent guthaben gestoppt nutzung monat`},pt:{q:`Por que a IA parou? Como funciona o limite?`,a:`Cada plano pago tem uma cota mensal de IA. Quando acaba, a IA pausa até o mês seguinte, a menos que você compre créditos extras (Configurações > IA). O resto funciona. Este assistente não usa sua cota.`,k:`ia limite cota créditos parou uso mês`},fr:{q:`Pourquoi l'IA s'est arrêtée ?`,a:`Chaque formule payante a un quota mensuel d'IA. Une fois épuisé, l'IA est en pause jusqu'au mois suivant, sauf achat de crédits (Réglages > IA). Le reste fonctionne. Cet assistant d'aide ne consomme pas votre quota.`,k:`ia limite quota crédits arrêtée usage mois`}}},{id:`calendar`,action:`connections`,t:{en:{q:`Can I connect Google Calendar or Outlook?`,a:`Yes. Settings > Connections lets you sync tasks both ways with Google Calendar or Outlook (tasks go to a separate "TaskRack" calendar) or subscribe to any calendar link so busy hours are respected when planning your day.`,k:`calendar google outlook sync ics connect events schedule busy`},tr:{q:`Google Takvim ya da Outlook bağlayabilir miyim?`,a:`Evet. Ayarlar > Bağlantılar'dan görevleri Google Takvim ya da Outlook ile iki yönlü eşitleyebilirsiniz (görevler ayrı bir "TaskRack" takvimine yazılır) ya da bir takvim adresine abone olup gün planında dolu saatlerin dikkate alınmasını sağlayabilirsiniz.`,k:`takvim google outlook eşitle ics bağla etkinlik dolu saat`},es:{q:`¿Puedo conectar Google Calendar u Outlook?`,a:`Sí. En Ajustes > Conexiones sincronizas tareas en ambos sentidos con Google Calendar u Outlook (en un calendario "TaskRack" aparte) o te suscribes a un enlace de calendario para respetar horas ocupadas.`,k:`calendario google outlook sincronizar conectar eventos`},de:{q:`Kann ich Google Kalender oder Outlook verbinden?`,a:`Ja. Unter Einstellungen > Verbindungen synchronisierst du Aufgaben in beide Richtungen mit Google Kalender oder Outlook (eigener "TaskRack"-Kalender) oder abonnierst einen Kalenderlink, damit belegte Zeiten beachtet werden.`,k:`kalender google outlook synchronisieren verbinden termine`},pt:{q:`Posso conectar Google Agenda ou Outlook?`,a:`Sim. Em Configurações > Conexões você sincroniza tarefas nos dois sentidos com Google Agenda ou Outlook (numa agenda "TaskRack" separada) ou assina um link de agenda para respeitar horários ocupados.`,k:`agenda calendário google outlook sincronizar conectar eventos`},fr:{q:`Puis-je connecter Google Agenda ou Outlook ?`,a:`Oui. Réglages > Connexions synchronise les tâches dans les deux sens avec Google Agenda ou Outlook (agenda « TaskRack » séparé) ou s'abonne à un lien d'agenda pour respecter les heures occupées.`,k:`agenda calendrier google outlook synchroniser connecter`}}},{id:`import`,action:`import`,t:{en:{q:`How do I move my tasks from another app?`,a:`Open Tools > Move from another app in the side menu. Connect Todoist, Asana, Trello, ClickUp, Notion or monday.com, or upload a file. Each of your projects becomes a TaskRack project and sections become columns.`,k:`import move migrate transfer todoist asana trello clickup notion monday csv switch`},tr:{q:`Başka uygulamadaki görevlerimi nasıl taşırım?`,a:`Yan menüde Araçlar > Başka uygulamadan taşı'yı açın. Todoist, Asana, Trello, ClickUp, Notion ya da monday.com hesabınızı bağlayın veya dosya yükleyin. Her projeniz TaskRack'te bir proje, bölümler sütun olur.`,k:`içe aktar taşı aktar geçiş todoist asana trello clickup notion monday csv`},es:{q:`¿Cómo traigo mis tareas desde otra app?`,a:`Abre Herramientas > Importar en el menú lateral. Conecta Todoist, Asana, Trello, ClickUp, Notion o monday.com, o sube un archivo. Cada proyecto se convierte en un proyecto de TaskRack.`,k:`importar migrar todoist asana trello clickup notion monday`},de:{q:`Wie übernehme ich Aufgaben aus einer anderen App?`,a:`Öffne im Seitenmenü Werkzeuge > Importieren. Verbinde Todoist, Asana, Trello, ClickUp, Notion oder monday.com, oder lade eine Datei hoch. Jedes Projekt wird ein TaskRack-Projekt.`,k:`importieren umziehen todoist asana trello clickup notion monday`},pt:{q:`Como trago minhas tarefas de outro app?`,a:`Abra Ferramentas > Importar no menu lateral. Conecte Todoist, Asana, Trello, ClickUp, Notion ou monday.com, ou envie um arquivo. Cada projeto vira um projeto no TaskRack.`,k:`importar migrar todoist asana trello clickup notion monday`},fr:{q:`Comment importer mes tâches d'une autre app ?`,a:`Ouvrez Outils > Importer dans le menu latéral. Connectez Todoist, Asana, Trello, ClickUp, Notion ou monday.com, ou envoyez un fichier. Chaque projet devient un projet TaskRack.`,k:`importer migrer todoist asana trello clickup notion monday`}}},{id:`plans`,action:`upgrade`,t:{en:{q:`How do plans, cancelling and refunds work?`,a:`You can change or cancel your plan in the app at any time. Cancelling stops the next renewal and your plan stays active until the end of the paid period; your first payment can be refunded in full within 14 days; renewals and remaining days aren't refunded. iPhone and Android subscriptions are managed in your phone's settings.`,k:`plan price pricing upgrade cancel refund subscription pay billing money back trial`},tr:{q:`Paketler, iptal ve iade nasıl işler?`,a:`Paketinizi uygulamadan istediğiniz an değiştirebilir ya da iptal edebilirsiniz. İptal bir sonraki yenilemeyi durdurur; paketiniz ödediğiniz dönemin sonuna kadar açık kalır, ilk ödemenizde 14 gün içinde tam iade isteyebilirsiniz; yenileme ödemeleri ve kalan günler iade edilmez. iPhone ve Android abonelikleri telefon ayarlarından yönetilir.`,k:`paket fiyat yükselt iptal iade abonelik ödeme fatura deneme para`},es:{q:`¿Cómo funcionan los planes, la cancelación y los reembolsos?`,a:`Puedes cambiar o cancelar tu plan en la app cuando quieras. Cancelar detiene la renovación y el plan sigue hasta el final del periodo pagado; tu primer pago se reembolsa por completo dentro de 14 días; las renovaciones y los días restantes no se reembolsan. En iPhone y Android se gestiona en los ajustes del teléfono.`,k:`plan precio cancelar reembolso suscripción pago prueba`},de:{q:`Wie funktionieren Pläne, Kündigung und Erstattung?`,a:`Du kannst deinen Plan jederzeit in der App ändern oder kündigen. Die Kündigung stoppt die Verlängerung, der Plan läuft bis zum Ende des bezahlten Zeitraums; die erste Zahlung wird innerhalb von 14 Tagen voll erstattet; Verlängerungen und Resttage werden nicht erstattet. iPhone- und Android-Abos verwaltest du in den Telefoneinstellungen.`,k:`plan preis kündigen erstattung abo zahlung test`},pt:{q:`Como funcionam planos, cancelamento e reembolso?`,a:`Você pode mudar ou cancelar o plano no app quando quiser. Cancelar interrompe a renovação e o plano segue até o fim do período pago; o primeiro pagamento pode ser reembolsado integralmente em até 14 dias; renovações e dias restantes não são reembolsados. No iPhone e Android, gerencie nas configurações do celular.`,k:`plano preço cancelar reembolso assinatura pagamento teste`},fr:{q:`Comment fonctionnent formules, résiliation et remboursement ?`,a:`Vous pouvez changer ou résilier votre formule dans l'app à tout moment. La résiliation arrête le renouvellement et la formule reste active jusqu'à la fin de la période payée ; le premier paiement est remboursable en totalité sous 14 jours ; les renouvellements et les jours restants ne sont pas remboursés. Sur iPhone et Android, gérez-le dans les réglages du téléphone.`,k:`formule prix résilier remboursement abonnement paiement essai`}}},{id:`offline`,t:{en:{q:`Does it work offline? Is my data synced?`,a:`Your personal tasks work offline and sync automatically when you're back online; the cloud icon in the top bar shows the sync status. Team workspaces need a connection.`,k:`offline internet sync cloud save lost data backup devices phone computer`},tr:{q:`İnternetsiz çalışır mı? Verilerim eşitleniyor mu?`,a:`Kişisel görevleriniz internet olmadan çalışır, bağlantı gelince kendiliğinden eşitlenir; üst çubuktaki bulut simgesi durumu gösterir. Ekip alanları bağlantı ister.`,k:`internetsiz çevrimdışı eşitleme bulut kaydet kayboldu veri yedek cihaz telefon bilgisayar`},es:{q:`¿Funciona sin conexión? ¿Se sincronizan mis datos?`,a:`Tus tareas personales funcionan sin conexión y se sincronizan al volver; el icono de nube muestra el estado. Los equipos necesitan conexión.`,k:`sin conexión sincronizar nube guardar datos dispositivos`},de:{q:`Funktioniert es offline? Werden Daten synchronisiert?`,a:`Persönliche Aufgaben funktionieren offline und synchronisieren automatisch, sobald du online bist; das Wolkensymbol zeigt den Status. Teams brauchen eine Verbindung.`,k:`offline synchronisieren cloud speichern daten geräte`},pt:{q:`Funciona offline? Meus dados sincronizam?`,a:`Suas tarefas pessoais funcionam offline e sincronizam ao voltar a conexão; o ícone de nuvem mostra o status. Equipes precisam de conexão.`,k:`offline sincronizar nuvem salvar dados dispositivos`},fr:{q:`Ça marche hors ligne ? Mes données sont-elles synchronisées ?`,a:`Vos tâches personnelles fonctionnent hors ligne et se synchronisent au retour de la connexion ; l'icône nuage indique l'état. Les équipes ont besoin d'une connexion.`,k:`hors ligne synchroniser nuage enregistrer données appareils`}}},{id:`delete-account`,action:`settings`,t:{en:{q:`How do I delete my account or export my data?`,a:`Settings > Account has Delete account; your personal data is removed. Above it, Export your data downloads everything (projects, tasks, notes, client pages with their approval and chat history) as JSON, or your task list as CSV, any time. If you own a team, it passes to the longest-standing member.`,k:`delete account remove export data download backup json csv privacy close leave gdpr`},tr:{q:`Hesabımı nasıl silerim ya da verilerimi nasıl dışa aktarırım?`,a:`Ayarlar > Hesap'ta Hesabı sil vardır; kişisel verileriniz silinir. Hemen üstündeki Verilerinizi dışa aktarın ile istediğiniz an her şeyi (projeler, görevler, notlar, onay ve sohbet geçmişiyle müşteri sayfaları) JSON, görev listesini CSV olarak indirebilirsiniz. Sahibi olduğunuz ekip en eski üyeye devredilir.`,k:`hesap sil kaldır dışa aktar veri indir yedek json csv gizlilik kapat ayrıl kvkk`},es:{q:`¿Cómo borro mi cuenta o exporto mis datos?`,a:`En Ajustes > Cuenta está Eliminar cuenta; se borran tus datos personales. Justo encima, Exporta tus datos descarga todo (proyectos, tareas, notas y páginas de cliente con su historial) en JSON, o tu lista de tareas en CSV, cuando quieras. Si eres dueño de un equipo, pasa al miembro más antiguo.`,k:`borrar cuenta eliminar exportar datos privacidad`},de:{q:`Wie lösche ich mein Konto oder exportiere Daten?`,a:`Unter Einstellungen > Konto findest du Konto löschen; persönliche Daten werden entfernt. Darüber lädt Daten exportieren jederzeit alles (Projekte, Aufgaben, Notizen, Kundenseiten mit Verlauf) als JSON oder deine Aufgabenliste als CSV herunter. Ein eigenes Team geht an das älteste Mitglied.`,k:`konto löschen exportieren daten datenschutz`},pt:{q:`Como excluo minha conta ou exporto dados?`,a:`Em Configurações > Conta há Excluir conta; seus dados pessoais são removidos. Logo acima, Exporte seus dados baixa tudo (projetos, tarefas, notas e páginas de cliente com histórico) em JSON, ou sua lista de tarefas em CSV, quando quiser. Se você é dono de uma equipe, ela passa ao membro mais antigo.`,k:`excluir conta exportar dados privacidade lgpd`},fr:{q:`Comment supprimer mon compte ou exporter mes données ?`,a:`Réglages > Compte propose Supprimer le compte ; vos données personnelles sont effacées. Juste au-dessus, Exporter vos données télécharge tout (projets, tâches, notes, pages client avec leur historique) en JSON, ou votre liste de tâches en CSV, à tout moment. Une équipe dont vous êtes propriétaire passe au membre le plus ancien.`,k:`supprimer compte exporter données confidentialité rgpd`}}},{id:`referral`,action:`settings`,t:{en:{q:`How do invites lower my price?`,a:`Settings > Account has your invite link. Once 2 people who signed up through it start their own paid subscription, your Pro plan drops to the Team price ($16.99 instead of $19.99 a month) from your next invoice. Trials and gifts don't count; if one stops paying you get 30 days. It applies to Pro bought on the web or desktop, not the Founder price or App Store / Google Play.`,k:`invite referral link friend discount team price cheaper reward`},tr:{q:`Davet ederek fiyatım nasıl düşer?`,a:`Ayarlar > Hesap'ta davet bağlantınız var. Bu bağlantıyla kaydolup kendi ücretli aboneliğini başlatan 2 kişi olunca Pro aboneliğiniz bir sonraki faturadan itibaren Ekip fiyatına iner (aylık 19,99 $ yerine 16,99 $). Deneme ve hediye sayılmaz; biri ödemeyi bırakırsa 30 gün süre tanınır. Web ya da masaüstünden alınan Pro'da geçerlidir; kurucu fiyatında ve App Store / Google Play aboneliğinde geçmez.`,k:`davet referans bağlantı arkadaş indirim ekip fiyatı ucuz ödül`},es:{q:`¿Cómo bajan mi precio las invitaciones?`,a:`En Ajustes > Cuenta está tu enlace de invitación. Cuando 2 personas que se registraron con él inicien su propia suscripción de pago, tu plan Pro baja al precio de Equipo (16,99 $ en lugar de 19,99 $ al mes) desde tu próxima factura. Las pruebas y los regalos no cuentan; si alguien deja de pagar tienes 30 días. Vale para Pro comprado en la web o el escritorio, no con el precio Fundador ni App Store / Google Play.`,k:`invitar referido enlace amigo descuento precio equipo`},de:{q:`Wie senken Einladungen meinen Preis?`,a:`Unter Einstellungen > Konto findest du deinen Einladungslink. Sobald 2 Personen, die sich darüber registriert haben, ein eigenes bezahltes Abo starten, sinkt dein Pro-Abo ab der nächsten Rechnung auf den Team-Preis (16,99 $ statt 19,99 $ im Monat). Testphasen und Geschenke zählen nicht; hört jemand auf zu zahlen, hast du 30 Tage. Gilt für Pro aus Web oder Desktop, nicht für den Gründerpreis oder App Store / Google Play.`,k:`einladen empfehlung link freund rabatt team preis`},pt:{q:`Como os convites baixam meu preço?`,a:`Em Configurações > Conta está seu link de convite. Quando 2 pessoas que se cadastraram por ele iniciarem a própria assinatura paga, seu plano Pro cai para o preço de Equipe (US$ 16,99 em vez de US$ 19,99 por mês) a partir da próxima fatura. Testes e presentes não contam; se alguém parar de pagar, você tem 30 dias. Vale para o Pro comprado na web ou no desktop, não para o preço Fundador nem App Store / Google Play.`,k:`convidar indicação link amigo desconto preço equipe`},fr:{q:`Comment les invitations baissent-elles mon prix ?`,a:`Réglages > Compte affiche votre lien d'invitation. Dès que 2 personnes inscrites avec ce lien démarrent leur propre abonnement payant, votre offre Pro passe au prix Équipe (16,99 $ au lieu de 19,99 $ par mois) à partir de votre prochaine facture. Les essais et cadeaux ne comptent pas ; si quelqu'un arrête de payer, vous avez 30 jours. Valable pour Pro acheté sur le web ou sur ordinateur, pas avec le prix Fondateur ni App Store / Google Play.`,k:`inviter parrainage lien ami réduction prix équipe`}}},{id:`department-assign`,t:{en:{q:`How do I give a task to a whole department?`,a:`In the task window or the task details, pick a department under Assign to a department. Everyone in it sees the task; the first person who taps I'll take it gets it, and the card shows the department until then.`,k:`department assign team pool claim take it sales marketing`},tr:{q:`Bir işi bütün departmana nasıl veririm?`,a:`Görev penceresinde ya da görev ayrıntısında Departmana ata'dan departmanı seçin. Departmandaki herkes görür; Ben alıyorum diyen ilk kişiye kalır, o zamana kadar kartta departmanın adı yazar.`,k:`departman ata ekip havuz üstlen ben alıyorum satış pazarlama`},es:{q:`¿Cómo asigno una tarea a todo un departamento?`,a:`En la ventana de la tarea o en sus detalles, elige un departamento en Asignar a un departamento. Todo el departamento la ve; quien toque Me la quedo se la queda.`,k:`departamento asignar equipo tomar`},de:{q:`Wie gebe ich eine Aufgabe an eine ganze Abteilung?`,a:`Wähle im Aufgabenfenster oder in den Details unter Einer Abteilung zuweisen die Abteilung. Alle dort sehen sie; wer auf Übernehme ich tippt, bekommt sie.`,k:`abteilung zuweisen team übernehmen`},pt:{q:`Como dou uma tarefa a um departamento inteiro?`,a:`Na janela da tarefa ou nos detalhes, escolha o departamento em Atribuir a um departamento. Todos veem; quem tocar em Eu pego fica com ela.`,k:`departamento atribuir equipe pegar`},fr:{q:`Comment confier une tâche à tout un service ?`,a:`Dans la fenêtre de la tâche ou ses détails, choisissez le service sous Attribuer à un service. Tout le service la voit ; la première personne qui touche Je m'en charge la prend.`,k:`service attribuer équipe prendre`}}},{id:`transfer-owner`,t:{en:{q:`How do I make someone else the team owner?`,a:`Team > Admin has Transfer team ownership. Pick a member and confirm; they become the owner and you stay as a member. The subscription stays billed to whoever pays.`,k:`transfer owner ownership admin boss hand over team`},tr:{q:`Ekip yetkisini başkasına nasıl veririm?`,a:`Ekip > Yönetim'de Ekip yetkisini devret vardır. Bir üye seçip onaylayın; o yetkili olur, siz üye olarak kalırsınız. Abonelik ödemesi ödeyen kişide kalır.`,k:`yetki devret sahip patron yönetici ekip`},es:{q:`¿Cómo hago a otra persona responsable del equipo?`,a:`En Equipo > Administración está Transferir la propiedad del equipo. Elige un miembro y confirma; tú sigues como miembro.`,k:`transferir propietario equipo`},de:{q:`Wie übertrage ich die Teamleitung?`,a:`Unter Team > Verwaltung findest du Teamleitung übertragen. Mitglied wählen und bestätigen; du bleibst Mitglied.`,k:`leitung übertragen team inhaber`},pt:{q:`Como passo a responsabilidade da equipe para outra pessoa?`,a:`Em Equipe > Administração há Transferir a responsabilidade da equipe. Escolha um membro e confirme; você continua como membro.`,k:`transferir responsável equipe`},fr:{q:`Comment transférer la responsabilité de l'équipe ?`,a:`Équipe > Administration propose Transférer la responsabilité de l'équipe. Choisissez un membre et confirmez ; vous restez membre.`,k:`transférer responsable équipe`}}},{id:`chat-pin-star`,t:{en:{q:`Can I pin or star chat messages?`,a:`Yes. Hover a message (or tap on a phone): the star saves it to your Starred messages list, only for you; the pin shows it at the top of the channel for everyone, up to 3. The team owner and managers pin in team channels; both people pin in a direct chat.`,k:`pin star chat message starred favourite`},tr:{q:`Sohbette mesaj sabitleyebilir ya da yıldızlayabilir miyim?`,a:`Evet. Mesajın yanındaki yıldız onu yalnızca sizin göreceğiniz Yıldızlı mesajlar listesine ekler; raptiye ise kanalın üstünde herkese gösterir (en fazla 3). Ekip kanallarında yetkili ve yöneticiler, birebirde iki taraf sabitler.`,k:`sabitle yıldız sohbet mesaj favori`},es:{q:`¿Puedo fijar o destacar mensajes del chat?`,a:`Sí. La estrella guarda el mensaje en tus Mensajes destacados; fijar lo muestra arriba del canal para todos (hasta 3).`,k:`fijar destacar chat mensaje`},de:{q:`Kann ich Chatnachrichten anheften oder markieren?`,a:`Ja. Der Stern speichert die Nachricht in deinen markierten Nachrichten; Anheften zeigt sie allen oben im Kanal (bis zu 3).`,k:`anheften markieren chat nachricht`},pt:{q:`Posso fixar ou favoritar mensagens no chat?`,a:`Sim. A estrela guarda a mensagem nas suas Mensagens favoritas; fixar mostra no topo do canal para todos (até 3).`,k:`fixar favoritar chat mensagem`},fr:{q:`Puis-je épingler ou mettre en favori des messages ?`,a:`Oui. L'étoile range le message dans vos Messages favoris ; l'épingle l'affiche en haut du canal pour tous (jusqu'à 3).`,k:`épingler favori chat message`}}},{id:`meeting-privacy`,t:{en:{q:`Can a team meeting end up on my client's page?`,a:`No. Meeting to tasks asks who the meeting was with and starts on Team only; a team meeting can't be published. For a client meeting you see and edit exactly what the client will read first, lines with prices or internal details are left out, and you can remove it later. Assistant chats never go to the client page.`,k:`meeting privacy client page publish internal team confidential`},tr:{q:`Ekip içi bir toplantı müşteri sayfasına düşebilir mi?`,a:`Hayır. Toplantıdan görevler toplantının kiminle yapıldığını sorar ve Ekip içi ile başlar; ekip içi toplantı yayınlanamaz. Müşteri toplantısında müşterinin okuyacağı metni önce görüp düzenlersiniz; fiyat ya da iç bilgi geçen satırlar dışarıda kalır ve yayını sonra kaldırabilirsiniz. Asistanla konuşmalar müşteri sayfasına hiç gitmez.`,k:`toplantı gizlilik müşteri sayfası yayın ekip içi gizli`},es:{q:`¿Puede una reunión interna acabar en la página del cliente?`,a:`No. Reunión a tareas pregunta con quién fue y empieza en Solo el equipo; una reunión interna no se puede publicar.`,k:`reunión privacidad cliente publicar interna`},de:{q:`Kann eine Teambesprechung auf der Kundenseite landen?`,a:`Nein. Besprechung zu Aufgaben fragt, mit wem sie war, und startet mit Nur das Team; interne Besprechungen lassen sich nicht veröffentlichen.`,k:`besprechung datenschutz kundenseite intern`},pt:{q:`Uma reunião interna pode ir para a página do cliente?`,a:`Não. Reunião em tarefas pergunta com quem foi e começa em Só a equipe; reunião interna não pode ser publicada.`,k:`reunião privacidade cliente interna`},fr:{q:`Une réunion d'équipe peut-elle finir sur la page client ?`,a:`Non. Réunion en tâches demande avec qui elle a eu lieu et commence sur Équipe seulement ; une réunion interne ne peut pas être publiée.`,k:`réunion confidentialité page client interne`}}},{id:`dictate`,t:{en:{q:`Can I dictate a task name?`,a:`Yes. Tap the microphone in the task name. It uses your device's speech recognition, so it doesn't use AI credits. In the Windows app, press Win + H to dictate.`,k:`voice dictate microphone speak task name`},tr:{q:`Görev adını konuşarak yazabilir miyim?`,a:`Evet. Görev adındaki mikrofona dokunun. Cihazınızın konuşma tanımasını kullanır, yapay zekâ hakkından düşmez. Windows uygulamasında Win + H ile dikte edebilirsiniz.`,k:`ses konuşarak yaz mikrofon dikte görev adı`},es:{q:`¿Puedo dictar el nombre de una tarea?`,a:`Sí. Toca el micrófono en el nombre de la tarea. Usa el reconocimiento de voz del dispositivo, sin créditos de IA.`,k:`dictar voz micrófono tarea`},de:{q:`Kann ich einen Aufgabennamen diktieren?`,a:`Ja. Tippe auf das Mikrofon im Aufgabennamen. Es nutzt die Spracherkennung deines Geräts, ohne KI-Guthaben.`,k:`diktieren sprache mikrofon aufgabe`},pt:{q:`Posso ditar o nome de uma tarefa?`,a:`Sim. Toque no microfone no nome da tarefa. Usa o reconhecimento de voz do aparelho, sem créditos de IA.`,k:`ditar voz microfone tarefa`},fr:{q:`Puis-je dicter le nom d'une tâche ?`,a:`Oui. Touchez le micro dans le nom de la tâche. Il utilise la reconnaissance vocale de l'appareil, sans crédits d'IA.`,k:`dicter voix micro tâche`}}},{id:`zapier`,action:`settings`,t:{en:{q:`Does TaskRack work with Zapier?`,a:`Yes. Settings > Integrations > Zapier creates a key you paste into Zapier. Zaps can start when a client approves, asks for changes, a step is done or a project is delivered, and they can open a client project from a template, add a task or a quick note.`,k:`zapier make automation webhook zap trigger action`},tr:{q:`TaskRack Zapier ile çalışır mı?`,a:`Evet. Ayarlar > Entegrasyonlar > Zapier'den bir anahtar oluşturup Zapier'e yapıştırırsınız. Zap'ler müşteri onaylayınca, değişiklik isteyince, bir adım bitince ya da proje teslim edilince başlayabilir; şablondan müşteri projesi, görev ya da hızlı not açabilir.`,k:`zapier make otomasyon zap tetikleyici eylem`},es:{q:`¿TaskRack funciona con Zapier?`,a:`Sí. En Ajustes > Integraciones > Zapier creas una clave para pegarla en Zapier. Los Zaps pueden empezar cuando el cliente aprueba, pide cambios, termina un paso o se entrega el proyecto, y pueden abrir un proyecto de cliente, una tarea o una nota.`,k:`zapier automatización zap`},de:{q:`Funktioniert TaskRack mit Zapier?`,a:`Ja. Unter Einstellungen > Integrationen > Zapier erstellst du einen Schlüssel für Zapier. Zaps starten bei Freigabe, Änderungswunsch, fertigem Schritt oder Lieferung und können Kundenprojekte, Aufgaben und Notizen anlegen.`,k:`zapier automatisierung zap`},pt:{q:`O TaskRack funciona com o Zapier?`,a:`Sim. Em Configurações > Integrações > Zapier você cria uma chave para colar no Zapier. Os Zaps podem começar quando o cliente aprova, pede alterações, uma etapa termina ou o projeto é entregue, e podem abrir projeto de cliente, tarefa ou nota.`,k:`zapier automação zap`},fr:{q:`TaskRack fonctionne-t-il avec Zapier ?`,a:`Oui. Réglages > Intégrations > Zapier crée une clé à coller dans Zapier. Les Zaps démarrent quand le client approuve, demande des modifications, qu'une étape est terminée ou que le projet est livré, et peuvent ouvrir un projet client, une tâche ou une note.`,k:`zapier automatisation zap`}}},{id:`hubspot`,action:`settings`,t:{en:{q:`Can a won HubSpot deal start a client project?`,a:`Yes. Connect HubSpot in Settings > Integrations, then pick the deal stage, the client template and where the project opens. When a deal reaches that stage your Agenda asks to open the project, or it opens automatically if you turn that on. Approvals and deliveries are added to the deal as notes. Nothing is emailed to the client automatically.`,k:`hubspot crm deal won pipeline client project`},tr:{q:`HubSpot'ta kazanılan anlaşma müşteri projesi açabilir mi?`,a:`Evet. Ayarlar > Entegrasyonlar'dan HubSpot'u bağlayıp anlaşma aşamasını, müşteri şablonunu ve projenin açılacağı alanı seçin. Anlaşma o aşamaya gelince Gündem projeyi açmak isteyip istemediğinizi sorar ya da isterseniz kendiliğinden açılır. Onay ve teslim bilgisi anlaşmaya not olarak düşer. Müşteriye kendiliğinden e-posta gitmez.`,k:`hubspot crm anlaşma kazanıldı müşteri projesi`},es:{q:`¿Un trato ganado en HubSpot puede abrir un proyecto de cliente?`,a:`Sí. Conecta HubSpot en Ajustes > Integraciones y elige la etapa, la plantilla y dónde se abre el proyecto. Cuando el trato llega a esa etapa, tu Agenda pregunta si abrir el proyecto.`,k:`hubspot crm trato ganado`},de:{q:`Kann ein gewonnener HubSpot-Deal ein Kundenprojekt starten?`,a:`Ja. Verbinde HubSpot unter Einstellungen > Integrationen und wähle Phase, Vorlage und Bereich. Erreicht der Deal die Phase, fragt deine Agenda, ob das Projekt geöffnet werden soll.`,k:`hubspot crm deal gewonnen`},pt:{q:`Um negócio ganho no HubSpot pode abrir um projeto de cliente?`,a:`Sim. Conecte o HubSpot em Configurações > Integrações e escolha a etapa, o modelo e onde o projeto abre. Quando o negócio chega a essa etapa, sua Agenda pergunta se deve abrir o projeto.`,k:`hubspot crm negócio ganho`},fr:{q:`Une transaction gagnée dans HubSpot peut-elle ouvrir un projet client ?`,a:`Oui. Connectez HubSpot dans Réglages > Intégrations et choisissez l'étape, le modèle et l'espace. Quand la transaction atteint cette étape, votre Agenda propose d'ouvrir le projet.`,k:`hubspot crm transaction gagnée`}}}],T=_();function E(){let e=h(e=>e.helpOpen),t=h(e=>e.setHelpOpen);return(0,T.jsx)(a,{children:e&&(0,T.jsx)(i.div,{className:`fixed inset-0 z-50 flex items-end justify-center bg-ink/50 backdrop-blur-sm sm:items-center sm:p-6`,initial:{opacity:0},animate:{opacity:1},exit:{opacity:0},onMouseDown:e=>e.target===e.currentTarget&&t(!1),children:(0,T.jsx)(F,{onClose:()=>t(!1)})})})}var D=[`en`,`tr`,`es`,`de`,`pt`,`fr`],O=[`share`,`private-link`,`priority`,`client-templates`,`payments`,`quick-notes`],k=e=>e.toLocaleLowerCase(`tr`).replace(/ı/g,`i`).no